      start_date: "20190821"
      start_time: "11:15:00" // originally scheduled at 11:15
    }
    stop_time_update {
	... // these are predicted arrival/departure times for the original trip
    }
  }
}
entity {
  id: "overload1"
  trip_update {
    trip: {
      trip_id: "TripId0"
      schedule_relationship: DUPLICATED
    }
    trip_properties {
      trip_id: "TripId0-Overload1"
      start_date: "20190821"
      start_time: "11:30:00" // extra trip running 15 minutes later
    }
    stop_time_update {
	... // QUESTION: are these predicted arrival/departure times? or the static times, shifted by 15 minutes?
